namespace sv_2a9335ee24e94262b62ca8c9f1093f32.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one instance per circuit) that holds theme state
/// and notifies subscribers when it changes.
/// </summary>
public sealed class ThemeService
{
    public ThemeMode Mode { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetMode(ThemeMode mode)
    {
        if (Mode == mode) return;
        Mode = mode;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }

    public void SetTheme(ThemeMode mode, string accentColor)
    {
        var changed = Mode != mode || AccentColor != accentColor;
        Mode = mode;
        AccentColor = accentColor;
        if (changed) OnChange?.Invoke();
    }
}

@* Interactive component placed in the static layout.
   On first render and on every theme change it pushes the
   current theme into the DOM via JS interop so that even
   static markup picks up the CSS class / custom property. *@

@rendermode InteractiveServer
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeAsync();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeAsync();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeAsync()
    {
        await JS.InvokeVoidAsync("ThemeInterop.apply",
            ThemeService.Mode.ToString().ToLowerInvariant(),
            ThemeService.AccentColor);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@* Interactive island in the header — re-renders whenever theme changes. *@

@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" title="Current theme">
    @switch (ThemeService.Mode)
    {
        case ThemeMode.Light: <span>☀️ Light</span> break;
        case ThemeMode.Dark:  <span>🌙 Dark</span>  break;
        default:              <span>💻 System</span> break;
    }
    <span class="accent-dot" style="background-color: @ThemeService.AccentColor;"></span>
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChange;
    }

    private async void HandleChange()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleChange;
    }
}

@* Quick theme-mode toggle — can be dropped into nav, header, or any page. *@

@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        title="Toggle theme">
    @switch (ThemeService.Mode)
    {
        case ThemeMode.Light: <span>☀️</span> break;
        case ThemeMode.Dark:  <span>🌙</span> break;
        default:              <span>💻</span> break;
    }
</button>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChange;
    }

    private void CycleTheme()
    {
        var next = ThemeService.Mode switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            _                => ThemeMode.Light
        };
        ThemeService.SetMode(next);
    }

    private async void HandleChange()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleChange;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h5>Theme Mode</h5>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <button class="btn @(ThemeService.Mode == mode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeService.SetMode(mode)">
                @mode
            </button>
        }
    </div>

    <h5>Accent Color</h5>
    <input type="color" class="form-control form-control-color mb-3"
           value="@ThemeService.AccentColor"
           @onchange="OnAccentChanged" />

    <p class="text-muted small">
        Changes apply instantly to all components, including the header indicator.
    </p>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChange;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private async void HandleChange()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleChange;
    }
}

// Applies theme to <html> so all markup (static + interactive) is themed.
window.ThemeInterop = {
    apply: function (mode, accentColor) {
        const html = document.documentElement;
        html.setAttribute("data-bs-theme", mode === "system" ? "" : mode);
        html.style.setProperty("--accent-color", accentColor);
    }
};

