// Applies theme to <html> so all markup (static + interactive) is themed.
window.ThemeInterop = {
    apply: function (mode, accentColor) {
        const html = document.documentElement;
        html.setAttribute("data-bs-theme", mode === "system" ? "" : mode);
        html.style.setProperty("--accent-color", accentColor);
    }
};

namespace sv_2a9335ee24e94262b62ca8c9f1093f32.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one instance per circuit) that holds theme state
/// and notifies subscribers when it changes.
/// </summary>
public sealed class ThemeService
{
    public ThemeMode Mode { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetMode(ThemeMode mode)
    {
        if (Mode == mode) return;
        Mode = mode;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }

    public void SetTheme(ThemeMode mode, string accentColor)
    {
        var changed = Mode != mode || AccentColor != accentColor;
        Mode = mode;
        AccentColor = accentColor;
        if (changed) OnChange?.Invoke();
    }
}

