@* Interactive component placed in the static layout.
   On first render and on every theme change it pushes the
   current theme into the DOM via JS interop so that even
   static markup picks up the CSS class / custom property. *@

@rendermode InteractiveServer
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeAsync();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeAsync();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeAsync()
    {
        await JS.InvokeVoidAsync("ThemeInterop.apply",
            ThemeService.Mode.ToString().ToLowerInvariant(),
            ThemeService.AccentColor);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

